#include "core.h"
#include <fstream>
#include <sstream>
#include <chrono>
#include <algorithm>
#include <psapi.h>
namespace xm {
static void Write(const fs::path& p,const std::string& value){fs::create_directories(p.parent_path());std::ofstream out(p,std::ios::binary);out.write(value.data(),value.size());if(!out)throw Failure(L"测试文件写入失败。");}
static std::string Read(const fs::path& p){std::ifstream in(p,std::ios::binary);return {std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};}
static void Require(bool value,const wchar_t* message){if(!value)throw Failure(message);}
static void Compare(const fs::path& a,const fs::path& b){Require(fs::exists(b),L"缺少解压结果");for(const auto& e:fs::recursive_directory_iterator(a)){auto dest=b/e.path().lexically_relative(a);Require(fs::exists(dest),L"缺少文件或空目录");if(e.is_regular_file())Require(Read(e.path())==Read(dest),L"文件内容不匹配");}}
static bool Clean(const fs::path& p){for(const auto& e:fs::recursive_directory_iterator(p))if(e.path().filename().wstring().rfind(L".xiaoma-work-",0)==0)return false;return true;}
int SelfTest(const fs::path& binary,const fs::path& root){std::ostringstream report;int passed=0,failed=0;fs::create_directories(root);Engine engine(binary);std::atomic_bool stop{false};auto begin=std::chrono::steady_clock::now();auto sample=root/L"样本 中文 空格";auto output=root/L"输出";fs::create_directories(output);Write(sample/L"中文文件.txt",ToUtf8(L"小马压缩测试：中文路径、空格、UTF-8。\n"));Write(sample/L"空文件.txt","");Write(sample/L"嵌套"/L"nested.txt",std::string(100000,'a'));fs::create_directories(sample/L"空目录");
 std::string random(5*1024*1024,0);unsigned state=123456;for(auto& c:random){state^=state<<13;state^=state>>17;state^=state<<5;c=(char)state;}Write(sample/L"随机数据.bin",random);
 auto test=[&](const wchar_t* label,const std::function<void()>& action){stop=false;auto t=std::chrono::steady_clock::now();try{action();passed++;report<<"PASS ";}catch(const Failure& e){failed++;report<<"FAIL "<<ToUtf8(e.message)<<" | ";}catch(const std::exception& e){failed++;report<<"FAIL "<<e.what()<<" | ";}catch(...){failed++;report<<"FAIL unexpected | ";}report<<ToUtf8(label)<<" | "<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count()<<" ms\n";};
 std::vector<fs::path> selected{sample};
 for(const auto& format:{L"zip",L"7z",L"tar"})test((std::wstring(format)+L" 压缩/列目录/校验/解压/逐字节比较").c_str(),[&](){Options o;o.format=format;auto pack=root/(std::wstring(L"普通.")+format);auto artifacts=engine.Compress(selected,pack,o,stop);Require(artifacts.size()==1,L"结果数量不符");auto list=engine.List(pack,L"",stop);Require(list.entries.size()>=6,L"目录条目缺失");engine.Test(pack,L"",stop);auto result=engine.Extract(pack,output,L"",stop);Compare(sample,result/sample.filename());});
 for(const auto& format:{L"zip",L"7z"})test((std::wstring(format)+L" AES 密码/错误密码拒绝/解压").c_str(),[&](){Options o;o.format=format;o.password=o.format==L"zip"?L"sample-123!":L"中文密码 sample-123!";auto pack=root/(std::wstring(L"加密.")+format);engine.Compress(selected,pack,o,stop);bool denied=false;try{engine.Extract(pack,output,L"wrong-password",stop);}catch(const Failure&){denied=true;}Require(denied,L"错误密码未被拒绝");auto result=engine.Extract(pack,output,o.password,stop);Compare(sample,result/sample.filename());Require(Clean(output),L"失败密码遗留临时目录");});
 test(L"ZIP 中文密码提供明确提示/不留下压缩包",[&](){Options o;o.password=L"中文密码";bool denied=false;try{engine.Compress(selected,root/L"中文密码.zip",o,stop);}catch(const Failure& e){denied=e.message.find(L"7z")!=std::wstring::npos;}Require(denied,L"ZIP 中文密码提示不明确");Require(!fs::exists(root/L"中文密码.zip"),L"留下中文密码 ZIP 半成品");});
 test(L"7z 分卷/自动续卷解压",[&](){Options o;o.format=L"7z";o.volumeMB=1;auto parts=engine.Compress(selected,root/L"分卷.7z",o,stop);Require(parts.size()>=5,L"分卷数量不符");auto result=engine.Extract(parts.front(),output,L"",stop);Compare(sample,result/sample.filename());});
 test(L"重名自动避让/保留原结果",[&](){auto first=engine.Extract(root/L"普通.zip",output,L"",stop);auto second=engine.Extract(root/L"普通.zip",output,L"",stop);Require(first!=second,L"同名结果覆盖");Compare(sample,first/sample.filename());Compare(sample,second/sample.filename());});
 test(L"压缩目标在源目录内时拒绝",[&](){bool denied=false;try{engine.Compress(selected,sample/L"inside.zip",Options{},stop);}catch(const Failure&){denied=true;}Require(denied,L"递归输出未拒绝");});
 test(L"已有压缩包不覆盖",[&](){auto before=Read(root/L"普通.zip");bool denied=false;try{engine.Compress(selected,root/L"普通.zip",Options{},stop);}catch(const Failure&){denied=true;}Require(denied,L"未拒绝覆盖");Require(before==Read(root/L"普通.zip"),L"已有压缩包被改变");});
 test(L"后台处理中取消压缩/临时目录清理",[&](){Options o;o.format=L"7z";o.level=7;bool cancelled=false;auto reporter=[&](const Progress& p){if(p.percent>=0)stop=true;};try{engine.Compress(selected,root/L"取消.7z",o,stop,reporter);}catch(const Cancelled&){cancelled=true;}Require(cancelled,L"取消未生效");Require(!fs::exists(root/L"取消.7z"),L"留下半成品");Require(Clean(root),L"取消遗留临时目录");});
 test(L"后台处理中取消解压/临时目录清理",[&](){bool cancelled=false;try{engine.Extract(root/L"普通.zip",output,L"",stop,[&](const Progress& p){if(p.percent>=0)stop=true;});}catch(const Cancelled&){cancelled=true;}Require(cancelled,L"取消未生效");Require(Clean(root),L"解压取消遗留临时目录");});
 test(L"路径穿越/绝对路径/ADS/设备名验证",[&](){for(const auto& name:{L"../escape.txt",L"a/../../escape.txt",L"C:\\escape.txt",L"\\\\server\\share",L"file:stream",L"CON.txt",L"dir/NUL",L"name. ",L"a\\..\\out.txt"}){bool denied=false;try{ValidateEntry(name);}catch(const Failure&){denied=true;}Require(denied,L"危险路径未被拒绝");}ValidateEntry(L"./安全路径/中文.txt");});
 test(L"损坏包拒绝/不留输出",[&](){Write(root/L"损坏.zip","invalid zip data");bool denied=false;try{engine.Extract(root/L"损坏.zip",output,L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"损坏包未被拒绝");Require(!fs::exists(output/L"损坏"),L"损坏包留下输出");});
 const auto fixtures=root.parent_path()/L"fixtures";
 for(const auto& name:{L"rar5.rar",L"密码.rar",L"tar.gz",L"sample.cab",L"source.txt.gz",L"source.txt.bz2",L"source.txt.xz",L"source.txt.zst"})test((std::wstring(name)+L" 独立内核解压").c_str(),[&](){Require(fs::exists(fixtures/name),L"测试样本缺失");auto result=engine.Extract(fixtures/name,output,std::wstring(name)==L"密码.rar"?L"sample-123":L"",stop);Require(Read(result/L"source.txt")==Read(fixtures/L"source.txt"),L"外部格式内容不匹配");});
 test(L"RAR 分卷解压",[&](){auto result=engine.Extract(fixtures/L"vol.part1.rar",output,L"",stop);Require(Read(result/L"random.bin")==Read(fixtures/L"random.bin"),L"RAR 分卷内容不匹配");});
 for(const auto& name:{L"traversal.zip",L"absolute.zip",L"ads.zip",L"device.zip",L"symlink.zip",L"tar-link.tar",L"tar-link.tgz"})test((std::wstring(name)+L" 实际恶意压缩包拒绝").c_str(),[&](){bool denied=false;try{engine.Extract(fixtures/name,output,L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"危险压缩包未被拒绝");Require(Clean(root),L"拒绝后遗留临时目录");});
 test(L"20000 条目录读取（虚拟列表）",[&](){auto list=engine.List(fixtures/L"many.zip",L"",stop);Require(list.entries.size()==20000,L"大目录条目缺失");});
 test(L"均衡/更小 7z 与 ZIP",[&](){for(auto format:{L"zip",L"7z"})for(int level:{5,7}){Options o;o.format=format;o.level=level;auto pack=root/(std::wstring(format)+std::to_wstring(level)+L"."+format);engine.Compress({sample/L"嵌套"},pack,o,stop);auto result=engine.Extract(pack,output,L"",stop);Compare(sample/L"嵌套",result/L"嵌套");}});

 test(L"流式检查 20000 条目录：不保存条目",[&](){auto a=engine.Inspect(fixtures/L"many.zip",L"",stop);Require(a.entries.empty()&&a.count==20000&&a.total==20000,L"流式检查统计不符");});
 test(L"仅提取选中文件",[&](){auto member=sample.filename().wstring()+L"\\中文文件.txt";auto result=engine.Extract(root/L"普通.zip",output,L"",stop,{}, {member});Require(Read(result/sample.filename()/L"中文文件.txt")==Read(sample/L"中文文件.txt"),L"选中文件内容错误");Require(!fs::exists(result/sample.filename()/L"随机数据.bin"),L"提取了未选文件");});
 test(L"选中目录递归提取及空目录",[&](){auto base=sample.filename().wstring();auto result=engine.Extract(root/L"普通.7z",output,L"",stop,{}, {base+L"\\嵌套",base+L"\\空目录"});Compare(sample/L"嵌套",result/sample.filename()/L"嵌套");Require(fs::is_directory(result/sample.filename()/L"空目录"),L"空目录未提取");Require(!fs::exists(result/sample.filename()/L"中文文件.txt"),L"提取了无关文件");});
 test(L"不存在的选中条目拒绝",[&](){bool denied=false;try{engine.Extract(root/L"普通.zip",output,L"",stop,{}, {L"missing.txt"});}catch(const Failure&){denied=true;}Require(denied,L"不存在条目未拒绝");Require(Clean(root),L"留下临时目录");});
 test(L"包内 UTF-8 文本只读预览与临时清理",[&](){auto text=engine.ReadText(root/L"普通.zip",sample.filename().wstring()+L"\\中文文件.txt",L"",stop);Require(text.find(L"小马压缩测试")!=std::wstring::npos&&text.find(L"\r\n")!=std::wstring::npos,L"UTF-8 预览错误");});
 test(L"UTF-16LE 文本预览与 2 MB 上限",[&](){auto folder=root/L"预览源";Write(folder/L"utf16.txt",std::string("\xff\xfe\x2d\x4e\x87\x65",6));Write(folder/L"large.txt",std::string(3*1024*1024,'x'));auto pack=root/L"预览.zip";engine.Compress({folder},pack,Options{},stop);Require(engine.ReadText(pack,L"预览源/utf16.txt",L"",stop)==L"中文",L"UTF-16 预览错误");bool denied=false;try{engine.ReadText(pack,L"预览源/large.txt",L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"超过预览上限未拒绝");});
 test(L"二进制内容不会执行或当作文本预览",[&](){bool denied=false;try{engine.ReadText(root/L"普通.zip",sample.filename().wstring()+L"\\随机数据.bin",L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"二进制预览未拒绝");});
 test(L"RAR 第二分卷自动定位首卷",[&](){Require(FirstVolume(fixtures/L"vol.part2.rar")==fs::absolute(fixtures/L"vol.part1.rar"),L"RAR 首卷定位失败");auto result=engine.Extract(fixtures/L"vol.part2.rar",output,L"",stop);Require(Read(result/L"random.bin")==Read(fixtures/L"random.bin"),L"非首卷解压错误");});
 test(L"7z 第二分卷自动定位与缺首卷拒绝",[&](){auto result=engine.Extract(root/L"分卷.7z.002",output,L"",stop);Compare(sample,result/sample.filename());Write(root/L"缺首卷.7z.002","x");bool denied=false;try{engine.Extract(root/L"缺首卷.7z.002",output,L"",stop);}catch(const Failure& e){denied=e.message.find(L"第一分卷")!=std::wstring::npos;}Require(denied,L"缺首卷提示失败");});
 test(L"ZIP/7z 仅打包与逐字节比对",[&](){for(auto fmt:{L"zip",L"7z"}){Options o;o.format=fmt;o.level=0;auto pack=root/(std::wstring(L"仅打包.")+fmt);engine.Compress({sample},pack,o,stop);auto result=engine.Extract(pack,output,L"",stop);Compare(sample,result/sample.filename());}});
 test(L"已压缩媒体智能跳过压缩",[&](){auto media=root/L"视频.mp4";Write(media,random);auto pack=root/L"智能.zip";engine.Compress({media},pack,Options{},stop);Require(fs::file_size(pack)<random.size()+1024,L"智能仅打包开销异常");auto result=engine.Extract(pack,output,L"",stop);Require(Read(result/L"视频.mp4")==random,L"智能打包内容不一致");});
 for(auto format:{L"zip",L"7z"})test((std::wstring(format)+L" 增加/覆盖/删除/原包备份比对").c_str(),[&](){auto pack=root/(std::wstring(L"修改.")+format);fs::copy_file(root/(std::wstring(L"普通.")+format),pack);auto before=Read(pack);auto addition=root/L"新增 中文.txt";Write(addition,"version one");auto backup=engine.Modify(pack,{addition},{},L"",stop);Require(Read(backup)==before,L"原包备份内容不一致");auto list=engine.List(pack,L"",stop);Require(std::any_of(list.entries.begin(),list.entries.end(),[](const Entry& e){return e.name==L"新增 中文.txt";}),L"新增内容不存在");Write(addition,"version two");engine.Modify(pack,{addition},{},L"",stop);auto result=engine.Extract(pack,output,L"",stop,{}, {L"新增 中文.txt"});Require(Read(result/L"新增 中文.txt")=="version two",L"覆盖内容不一致");engine.Modify(pack,{}, {L"新增 中文.txt",sample.filename().wstring()+L"\\嵌套"},L"",stop);list=engine.List(pack,L"",stop);Require(std::none_of(list.entries.begin(),list.entries.end(),[&](const Entry& e){return e.name==L"新增 中文.txt"||e.name.find(L"嵌套")!=std::wstring::npos;}),L"删除条目仍存在");Require(Clean(root),L"修改遗留临时目录");});
 test(L"加密 7z 修改仍保留目录加密",[&](){auto pack=root/L"修改加密.7z";fs::copy_file(root/L"加密.7z",pack);auto source=root/L"加密新增.txt";Write(source,"private test");engine.Modify(pack,{source},{},L"中文密码 sample-123!",stop);bool denied=false;try{engine.List(pack,L"",stop);}catch(const Failure& e){denied=e.password;}Require(denied,L"更新后失去目录加密");auto result=engine.Extract(pack,output,L"中文密码 sample-123!",stop,{}, {L"加密新增.txt"});Require(Read(result/L"加密新增.txt")=="private test",L"加密更新内容不一致");});
 test(L"更新失败/取消时保持原包逐字节不变",[&](){auto pack=root/L"修改失败.zip";fs::copy_file(root/L"普通.zip",pack);auto before=Read(pack);bool denied=false;try{engine.Modify(pack,{root/L"not-found.txt"},{},L"",stop);}catch(const Failure&){denied=true;}Require(denied&&Read(pack)==before,L"更新失败改变原包");stop=true;bool cancelled=false;try{engine.Modify(pack,{}, {sample.filename().wstring()+L"\\中文文件.txt"},L"",stop);}catch(const Cancelled&){cancelled=true;}stop=false;Require(cancelled&&Read(pack)==before,L"更新取消改变原包");Require(Clean(root),L"更新失败留下临时数据");});
 test(L"RAR 修改和分卷修改拒绝",[&](){for(auto p:{fixtures/L"rar5.rar",root/L"分卷.7z.001"}){auto before=Read(p);bool denied=false;try{engine.Modify(p,{}, {L"source.txt"},L"",stop);}catch(const Failure&){denied=true;}Require(denied&&Read(p)==before,L"不支持的包被改变");}});
 test(L"RAR 转 ZIP/ZIP 转 7z 原件保留",[&](){auto before=Read(fixtures/L"rar5.rar");auto parts=engine.Convert(fixtures/L"rar5.rar",root/L"转换.zip",Options{},L"",stop);auto result=engine.Extract(parts.front(),output,L"",stop);Require(Read(result/L"source.txt")==Read(fixtures/L"source.txt"),L"RAR 转 ZIP 内容错误");Require(Read(fixtures/L"rar5.rar")==before,L"转换改变原件");Options o;o.format=L"7z";parts=engine.Convert(root/L"普通.zip",root/L"转换.7z",o,L"",stop);result=engine.Extract(parts.front(),output,L"",stop);Compare(sample,result/sample.filename());});
 PROCESS_MEMORY_COUNTERS pm{};pm.cb=sizeof(pm);GetProcessMemoryInfo(GetCurrentProcess(),&pm,sizeof(pm));report<<"\nTOTAL "<<passed<<" passed, "<<failed<<" failed\nDuration seconds: "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<"\nTest runner peak working set bytes: "<<pm.PeakWorkingSetSize<<"\nEngine child peak working set bytes: "<<EnginePeakMemory()<<"\n";Write(root/L"测试报告.txt",report.str());return failed?1:0;
}
}
